import React from "react";
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faBriefcase } from '@fortawesome/free-solid-svg-icons';
import { VerticalTimeline, VerticalTimelineElement } from 'react-vertical-timeline-component';
import 'react-vertical-timeline-component/style.min.css';
import '../assets/styles/Timeline.scss';

function Timeline() {
    return (
        <div id="history">
            <div className="items-container">
                <h1>Career History</h1>
                <VerticalTimeline>

                    {/* 1. QA Tester (Most recent) */}
                    <VerticalTimelineElement
                        className="vertical-timeline-element--work"
                        contentStyle={{ background: 'white', color: 'rgb(39, 40, 34)' }}
                        contentArrowStyle={{ borderRight: '7px solid white' }}
                        date="Feb 2026 - Mar 2026"
                        iconStyle={{ background: '#5000ca', color: '#fff' }}
                        icon={<FontAwesomeIcon icon={faBriefcase} />}
                    >
                        <h3 className="vertical-timeline-element-title">QA Tester</h3>
                        <h4 className="vertical-timeline-element-subtitle">Shark Mind</h4>
                        <p>
                            Executed exploratory, functional, and usability (UX/UI) testing on the Quick FAQ and Safe Pet applications, identifying logical flaws, critical errors, and mobile responsiveness issues. Detailed and documented bugs found, providing key design and user flow suggestions to optimize the final user experience.
                        </p>
                    </VerticalTimelineElement>

                    {/* 2. Senior Developer */}
                    <VerticalTimelineElement
                        className="vertical-timeline-element--work"
                        contentStyle={{ background: 'white', color: 'rgb(39, 40, 34)' }}
                        contentArrowStyle={{ borderRight: '7px solid white' }}
                        date="Sept 2025 - Mar 2026"
                        iconStyle={{ background: '#5000ca', color: '#fff' }}
                        icon={<FontAwesomeIcon icon={faBriefcase} />}
                    >
                        <h3 className="vertical-timeline-element-title">Senior Developer</h3>
                        <h4 className="vertical-timeline-element-subtitle">Tienda Mayorista</h4>
                        <p>
                            Designed and implemented a responsive and dynamic interface using HTML5, CSS3, Bootstrap, and native JavaScript for seamless sales and menu management. Developed backend logic in PHP with a MySQL database, optimizing SQL queries for inventory control under a local environment configured with XAMPP and Composer.
                        </p>
                    </VerticalTimelineElement>

                    {/* 3. Support Developer */}
                    <VerticalTimelineElement
                        className="vertical-timeline-element--work"
                        contentStyle={{ background: 'white', color: 'rgb(39, 40, 34)' }}
                        contentArrowStyle={{ borderRight: '7px solid white' }}
                        date="Sept 2023 - Feb 2024"
                        iconStyle={{ background: '#5000ca', color: '#fff' }}
                        icon={<FontAwesomeIcon icon={faBriefcase} />}
                    >
                        <h3 className="vertical-timeline-element-title">Support Developer</h3>
                        <h4 className="vertical-timeline-element-subtitle">BMGroup</h4>
                        <p>
                            Optimized .NET systems for corporate clients, managed SQL Server databases, handled security access, and automated internal processes using Power BI and Microsoft Forms.
                        </p>
                    </VerticalTimelineElement>

                    {/* 4. Internship */}
                    <VerticalTimelineElement
                        className="vertical-timeline-element--work"
                        contentStyle={{ background: 'white', color: 'rgb(39, 40, 34)' }}
                        contentArrowStyle={{ borderRight: '7px solid white' }}
                        date="Feb 2023 - Mar 2023"
                        iconStyle={{ background: '#5000ca', color: '#fff' }}
                        icon={<FontAwesomeIcon icon={faBriefcase} />}
                    >
                        <h3 className="vertical-timeline-element-title">IT Internship</h3>
                        <h4 className="vertical-timeline-element-subtitle">Importadora de ideas S.A</h4>
                        <p>
                            Managed support incidents using Mantis, maintained multi-site technological and CCTV infrastructure, standardized processes through technical documentation, and promoted digital culture with cybersecurity newsletters.
                        </p>
                    </VerticalTimelineElement>

                    {/* 5. IT Assistant */}
                    <VerticalTimelineElement
                        className="vertical-timeline-element--work"
                        contentStyle={{ background: 'white', color: 'rgb(39, 40, 34)' }}
                        contentArrowStyle={{ borderRight: '7px solid white' }}
                        date="Sept 2021 - Dec 2021"
                        iconStyle={{ background: '#5000ca', color: '#fff' }}
                        icon={<FontAwesomeIcon icon={faBriefcase} />}
                    >
                        <h3 className="vertical-timeline-element-title">IT Assistant</h3>
                        <h4 className="vertical-timeline-element-subtitle">Confiteria Eli's</h4>
                        <p>
                            Trained staff on POS systems, provided specialized support in SAP, managed SQL Server/Access databases, audited CCTV systems, and managed multi-site IT equipment inventories.
                        </p>
                    </VerticalTimelineElement>

                </VerticalTimeline>
            </div>
        </div>
    );
}

export default Timeline;