import React, { useEffect, useState } from "react";
import AppBar from '@mui/material/AppBar';
import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import CssBaseline from '@mui/material/CssBaseline';
import DarkModeIcon from '@mui/icons-material/DarkMode';
import Divider from '@mui/material/Divider';
import Drawer from '@mui/material/Drawer';
import IconButton from '@mui/material/IconButton';
import LightModeIcon from '@mui/icons-material/LightMode';
import List from '@mui/material/List';
import ListIcon from '@mui/icons-material/List';
import ListItem from '@mui/material/ListItem';
import ListItemButton from '@mui/material/ListItemButton';
import ListItemText from '@mui/material/ListItemText';
import MenuIcon from '@mui/icons-material/Menu';
import Toolbar from '@mui/material/Toolbar';
import Menu from '@mui/material/Menu';
import MenuItem from '@mui/material/MenuItem';
import { faLanguage } from '@fortawesome/free-solid-svg-icons';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';

const drawerWidth = 240;
const navItems = [['Expertise', 'expertise'], ['History', 'history'], ['Projects', 'projects'], ['CV', 'contact']];

function Navigation({ parentToChild, modeChange }: any) {

    const { mode } = parentToChild;

    const [mobileOpen, setMobileOpen] = useState<boolean>(false);
    const [scrolled, setScrolled] = useState<boolean>(false);

    const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
    const [language, setLanguage] = useState<string>('ES');

    const handleDrawerToggle = () => {
        setMobileOpen((prevState) => !prevState);
    };

    const handleLangMenuOpen = (event: React.MouseEvent<HTMLElement>) => {
        setAnchorEl(event.currentTarget);
    };

    // 🌐 CONEXIÓN DIRECTA CON EL MOTOR DE GOOGLE TRANSLATE
    const handleLangMenuClose = (selectedLang?: string) => {
        setAnchorEl(null);
        if (selectedLang) {
            setLanguage(selectedLang);

            // Google Translate espera las iniciales en minúsculas ('es' o 'en')
            const googleLang = selectedLang.toLowerCase();

            // Buscamos el elemento select oculto que inyecta Google en el DOM
            const googleSelect = document.querySelector('.goog-te-combo') as HTMLSelectElement;

            if (googleSelect) {
                googleSelect.value = googleLang;
                // Forzamos el evento 'change' para que Google procese la traducción instantáneamente
                googleSelect.dispatchEvent(new Event('change'));
            } else {
                console.warn("El script de Google Translate aún no está disponible en la página.");
            }
        }
    };

    useEffect(() => {
        const handleScroll = () => {
            const navbar = document.getElementById("navigation");
            if (navbar) {
                const scrolled = window.scrollY > navbar.clientHeight;
                setScrolled(scrolled);
            }
        };

        window.addEventListener('scroll', handleScroll);

        return () => {
            window.removeEventListener('scroll', handleScroll);
        };
    }, []);

    const scrollToSection = (section: string) => {
        console.log(section)
        const expertiseElement = document.getElementById(section);
        if (expertiseElement) {
            expertiseElement.scrollIntoView({ behavior: 'smooth' });
            console.log('Scrolling to:', expertiseElement);
        } else {
            console.error('Element with id "expertise" not found');
        }
    };

    const drawer = (
        <Box className="navigation-bar-responsive" onClick={handleDrawerToggle} sx={{ textAlign: 'center' }}>
            <p className="mobile-menu-top"><ListIcon />Menu</p>
            <Divider />
            <List>
                {navItems.map((item) => (
                    <ListItem key={item[0]} disablePadding>
                        <ListItemButton sx={{ textAlign: 'center' }} onClick={() => scrollToSection(item[1])}>
                            <ListItemText primary={item[0]} />
                        </ListItemButton>
                    </ListItem>
                ))}
            </List>
        </Box>
    );

    return (
        <Box sx={{ display: 'flex' }}>
            <CssBaseline />
            <AppBar component="nav" id="navigation" className={`navbar-fixed-top${scrolled ? ' scrolled' : ''}`}>
                <Toolbar className='navigation-bar'>
                    <IconButton
                        color="inherit"
                        aria-label="open drawer"
                        edge="start"
                        onClick={handleDrawerToggle}
                        sx={{ mr: 2, display: { sm: 'none' } }}
                    >
                        <MenuIcon />
                    </IconButton>

                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                        <IconButton color="inherit" onClick={() => modeChange()} sx={{ p: 1 }}>
                            {mode === 'dark' ? <LightModeIcon /> : <DarkModeIcon />}
                        </IconButton>

                        <IconButton
                            color="inherit"
                            onClick={handleLangMenuOpen}
                            sx={{ p: 1, display: 'flex', gap: 0.5, borderRadius: '8px' }}
                        >
                            <FontAwesomeIcon icon={faLanguage} style={{ fontSize: '1.25rem' }} />
                            <Box component="span" sx={{ fontSize: '10pt', fontWeight: 'bold', minWidth: '20px', textAlign: 'left' }}>
                                {language}
                            </Box>
                        </IconButton>
                    </Box>

                    <Menu
                        anchorEl={anchorEl}
                        open={Boolean(anchorEl)}
                        onClose={() => handleLangMenuClose()}
                        disableScrollLock={true}
                        slotProps={{
                            paper: {
                                sx: { mt: 0.5, boxShadow: '0px 4px 20px rgba(0,0,0,0.15)' }
                            }
                        }}
                    >
                        <MenuItem onClick={() => handleLangMenuClose('ES')} selected={language === 'ES'} sx={{ fontSize: '11pt' }}>
                            Espa&ntilde;ol
                        </MenuItem>
                        <MenuItem onClick={() => handleLangMenuClose('EN')} selected={language === 'EN'} sx={{ fontSize: '11pt' }}>
                            English
                        </MenuItem>
                    </Menu>

                    <Box sx={{ display: { xs: 'none', sm: 'block' } }}>
                        {navItems.map((item) => (
                            <Button key={item[0]} onClick={() => scrollToSection(item[1])} sx={{ color: '#fff' }}>
                                {item[0]}
                            </Button>
                        ))}
                    </Box>
                </Toolbar>
            </AppBar>
            <nav>
                <Drawer
                    variant="temporary"
                    open={mobileOpen}
                    onClose={handleDrawerToggle}
                    ModalProps={{
                        keepMounted: true,
                    }}
                    sx={{
                        display: { xs: 'block', sm: 'none' },
                        '& .MuiDrawer-paper': { boxSizing: 'border-box', width: drawerWidth },
                    }}
                >
                    {drawer}
                </Drawer>
            </nav>
        </Box>
    );
}

export default Navigation;