import React from "react";
import GitHubIcon from '@mui/icons-material/GitHub';
import LinkedInIcon from '@mui/icons-material/LinkedIn';
import DownloadIcon from '@mui/icons-material/Download'; // <-- A�ade esta l�nea para el icono de descarga
import { Button, Stack } from '@mui/material'; // <-- A�ade esta l�nea para los componentes de Material UI
import '../assets/styles/Main.scss';
import mock44 from '../assets/images/imgg.jpeg';

function Main() {

  return (
    <div className="container">
      <div className="about-section">
        <div className="image-wrapper">
        <img src={mock44} alt="Avatar" />
        </div>
        <div className="content">
          <div className="social_icons">
            <a href="https://github.com/vEvelin" target="_blank" rel="noreferrer"><GitHubIcon/></a>
            <a href="https://www.linkedin.com/in/valeriaguarachi/" target="_blank" rel="noreferrer"><LinkedInIcon/></a>
          </div>
          <h1>Valeria Guarachi</h1>
          <p>Software Engineer</p>

                  {/* --- BLOQUE DE BOTONES DE DESCARGA DE CV --- */}
                  <Stack
                      direction={{ xs: 'column', sm: 'row' }} // Se apilan en vertical en celular y horizontal en pantallas grandes
                      spacing={2}
                      justifyContent="center"
                      alignItems="center"
                      sx={{ mt: 3, mb: 3 }}
                  >
                      <Button
                          component="a"
                          href={`${process.env.PUBLIC_URL}/CV_Valeria_Guarachi_ES.pdf`}
                          download="CV_Valeria_Guarachi_ES.pdf"
                          variant="contained"
                          startIcon={<DownloadIcon />}
                          sx={{
                              backgroundColor: '#8b5cf6',
                              '&:hover': {
                                  backgroundColor: '#7c3aed',
                              },
                              textTransform: 'none',
                              fontWeight: 'bold',
                              borderRadius: 2,
                              width: { xs: '100%', sm: 'auto' } // Ancho completo en m�vil para que sea f�cil presionar
                          }}
                      >
                          Descargar CV (Espa&ntilde;ol)
            </Button>

                      <Button
                          component="a"
                          href={`${process.env.PUBLIC_URL}/CV_Valeria_Guarachi_EN.pdf`} // Apunta al PDF en ingl�s que descargamos
                          download="CV_Valeria_Guarachi_EN.pdf"
                          variant="outlined"
                          startIcon={<DownloadIcon />}
                          sx={{
                              color: '#8b5cf6',
                              borderColor: '#8b5cf6',
                              '&:hover': {
                                  borderColor: '#7c3aed',
                                  backgroundColor: 'rgba(139, 92, 246, 0.08)',
                              },
                              textTransform: 'none',
                              fontWeight: 'bold',
                              borderRadius: 2,
                              width: { xs: '100%', sm: 'auto' }
                          }}
                      >
                          Download CV (English)
                    </Button>
                  </Stack>


          <div className="mobile_social_icons">
            <a href="https://github.com/vEvelin" target="_blank" rel="noreferrer"><GitHubIcon/></a>
            <a href="https://www.linkedin.com/in/valeriaguarachi/" target="_blank" rel="noreferrer"><LinkedInIcon/></a>
          </div>

        </div>
      </div>
    </div>
  );
}

export default Main;